take in mind the model guard but also Here is a direct patch targeting the two points of failure:

1. **The stream parser crashing** when OpenRouter injects a raw `502` / `error` payload into an active SSE stream instead of a completion delta.
2. **The transport socket collapsing** (`ConnectionClosed` in Bun / Node `fetch()`) when the upstream connection drops mid-generation.

---

### Patch 1: `@ai-sdk/provider-utils` / Stream Parser (`parse-json-event-stream.ts`)

This patch intercepts injected `502` / `provider_unavailable` error objects before they hit the schema validator, normalizes single-newline SSE delimiter issues, and raises a typed retryable error instead of fatally corrupting the session.

```diff
--- a/node_modules/@ai-sdk/provider-utils/dist/index.mjs
+++ b/node_modules/@ai-sdk/provider-utils/dist/index.mjs
@@ -1,6 +1,38 @@
 function parseJsonEventStream({ stream, schema }) {
   return stream
+    .pipeThrough(
+      new TransformStream({
+        transform(chunk, controller) {
+          // Handle upstream SSE boundary loss where events are delimited by \n instead of \n\n
+          const text = typeof chunk === "string" ? chunk : new TextDecoder().decode(chunk);
+          const lines = text.split(/\r?\n/);
+          for (const line of lines) {
+            if (line.startsWith("data: ")) {
+              const rawData = line.slice(6).trim();
+              if (rawData === "[DONE]") {
+                controller.enqueue(line + "\n\n");
+                continue;
+              }
+              try {
+                const parsed = JSON.parse(rawData);
+                // Intercept mid-stream 502 / provider error injection
+                if (parsed.error || parsed.type === "api_error" || parsed.code === 502) {
+                  const errMsg = parsed.error?.message || parsed.message || "Upstream 502 mid-stream injection";
+                  const err = new Error(`UpstreamStreamError [502]: ${errMsg}`);
+                  err.status = 502;
+                  err.isRetryable = true;
+                  controller.error(err);
+                  return;
+                }
+              } catch (_) {
+                // Chunk is incomplete or split across boundaries; pass through
+              }
+            }
+            controller.enqueue(line + "\n");
+          }
+        }
+      })
+    )
     .pipeThrough(new EventSourceParserStream())

```

---

### Patch 2: Bun / Client Transport Socket Guard (`fetch` Wrapper)

If your client (e.g. OpenCode, custom agent loop, or proxy) executes via Bun, Bun’s native HTTP client throws `ConnectionClosed: The socket connection was closed unexpectedly` whenever the remote finishes early.

Wrap your provider’s custom `fetch` implementation with an exponential retry handler for socket resets and 502s:

```typescript
// resilient-fetch.ts
export async function resilientFetch(
  url: string | URL | Request,
  init?: RequestInit,
  maxRetries = 3
): Promise<Response> {
  let attempt = 0;
  let delay = 1000;

  while (true) {
    try {
      const response = await fetch(url, {
        ...init,
        // Optional: pass verbose: false to silence standard err noise in Bun
      });

      // Catch initial non-200 502/503/504 gateways before streaming starts
      if ([502, 503, 504].includes(response.status) && attempt < maxRetries) {
        attempt++;
        await new Promise((r) => setTimeout(r, delay));
        delay *= 2;
        continue;
      }

      return response;
    } catch (err: any) {
      const isSocketClosed =
        err?.name === "ConnectionClosed" ||
        err?.message?.includes("socket connection was closed unexpectedly") ||
        err?.message?.includes("fetch failed") ||
        err?.code === "ECONNRESET";

      if (isSocketClosed && attempt < maxRetries) {
        attempt++;
        console.warn(`[Network] Upstream socket reset (${err.message}). Retrying ${attempt}/${maxRetries}...`);
        await new Promise((r) => setTimeout(r, delay));
        delay *= 2;
        continue;
      }

      throw err;
    }
  }
}

