    // Handle Shift+Tab (Backtab): move focus to previous result and autocomplete
    if (event.key === Qt.Key_Backtab) {
        if (!searchBar.searchInput.activeFocus && appResults.count > 0) {
            root.focusSearchInput();
            let prevIndex = appResults.currentIndex - 1;
            if (prevIndex >= 0) {
                let prevItem = appResults.itemAtIndex(prevIndex);
                if (prevItem) {
                    let text = prevItem.modelData.name;
                    LauncherSearch.query = text;
                    searchBar.searchInput.text = text;
                    event.accepted = true;
                }
            }
        }
        return;

    // Only handle visible printable characters (ignore control chars, arrows, etc.)
    if (event.text && event.text.length === 1 && event.key !== Qt.Key_Enter && event.key !== Qt.Key_Return && event.key !== Qt.Key_Delete && event.text.charCodeAt(0) >= 0x20) // ignore control chars like Backspace, Tab, etc.
    {
        if (!searchBar.searchInput.activeFocus) {
            root.focusSearchInput();
            // Insert the character at the cursor position
            searchBar.searchInput.text = searchBar.searchInput.text.slice(0, searchBar.searchInput.cursorPosition) + event.text + searchBar.searchInput.text.slice(searchBar.searchInput.cursorPosition);
            searchBar.searchInput.cursorPosition += 1;
            event.accepted = true;
            root.focusFirstItem();
        }
    }
